window.Game=window.Game||{};
(()=>{
let state=null,envelope=null,busy=false,conflict=false,setupStep=1;const ui=Game.ui,st=Game.storage,$=ui.$;
function announce(msg){ui.toast(msg);}
function render(status){Game.currentProfile=envelope?.profile;ui.render(state,envelope,status|| (conflict?'另一页面已更新 · 当前页只读':state?'已保存到本机':'离线单人游戏 · 无账户'));}
function persist(){try{envelope=st.save(envelope,state);conflict=false;return true;}catch(e){conflict=/另一标签页/.test(e.message);announce(e.message);return false;}}
function command(type,payload={}){if(busy||conflict)return;busy=true;try{const result=Game.dispatch(state,{type,payload,expectedRevision:state.revision});if(!result.ok){announce(({NO_AP:'今天的行动时段已用完。',INSUFFICIENT_ITEM:'物资不足。',MISSING_DOCUMENT:'还没有这份情报。',MISSING_FLAG:'需要先取得相关线索。',STALE_ACTION:'这个选项已过期，请查看最新情况。',NO_AMMO:'没有弹药，可以选择近战或逃跑。',FULL_HEALTH:'生命值已满。',RUN_ENDED:'本局已经结束。',INVALID_PHASE:'当前状态不能执行这个操作。',ROUTE_LOCKED:'需要先取得通行证或打通地下通道。',NO_STA:'体力不足，请先休息。',OVERWEIGHT:'负重超过上限，无法移动。',COMPANION_REQUIRED:'需要一名已招募的同行者协助救援。',RANDOM_EVENTS_DISABLED:'随机事件已关闭。',NO_EVENT:'此处已没有新的周边事件。',NOT_ADJACENT:'只能移动到相邻地点。'})[result.code]||`行动未执行：${result.code}`);return;}state=result.state;const msgs=result.messages||[];if(msgs.length)state.journal.unshift(...msgs);const saved=persist();render(conflict?'另一标签页已更新 · 当前进度只读；请先导出':state.phase==='ended'?(saved?'结局与图鉴已保存':'结局仅本次有效 · 尚未保存'):(saved?'已保存到本机':'仅本次有效 · 尚未保存；请导出进度'));if(state.phase==='ended')showEnding();}catch(e){announce(`操作未完成，存档保持原样：${e.message}`);}finally{busy=false;}}
function showEnding(){Game.currentProfile=envelope?.profile;ui.render(state,envelope);}
function initialize(){
 const loaded=st.load();envelope=loaded.envelope||st.empty();
 if(!loaded.ok){$('save-status').textContent='本地存档异常';ui.modal('存档需要恢复',`<p>检测到存档无法读取：${ui.esc(loaded.error||'浏览器存储不可用')}</p><p>原始本地数据已保留。可以先导出后再导入有效备份。</p>`,[{label:'导出原始数据',run:()=>{try{st.downloadRaw();}catch(e){announce(e.message);}}},{label:'知道了',primary:true}]);render('本地存档异常');return;}
 if(loaded.recovered){ui.modal('发现可用的旧备份',`<p>主存档无法读取，找到一份较早的有效备份。</p><p>确认恢复后会用这份备份替换损坏的主存档，可能缺少最近一次进度。你可以先导出恢复副本。</p>`,[{label:'导出恢复副本',run:()=>st.download(loaded.envelope)},{label:'暂不恢复',run:()=>{state=null;render('主存档未恢复 · 数据仍保留');}},{label:'确认恢复备份',primary:true,run:()=>{envelope=loaded.envelope;state=envelope.slots.auto?.state||null;try{envelope=st.write(envelope);render('已从备份恢复');}catch(e){render('备份已读取 · 尚未覆盖主档');announce(e.message);}}}]);render('主存档需恢复');return;}
 if(envelope.slots.auto?.state)state=envelope.slots.auto.state;render();
}function newGame(config){const a=envelope.slots.auto?.state;if(a&&a.phase!=='ended'&&!confirm(`自动槽中有 ${a.player.name} 的进度。开始新人生会覆盖自动槽；其他手动槽不变。继续？`))return;const seedBytes=new Uint32Array(1);try{window.crypto.getRandomValues(seedBytes);}catch{seedBytes[0]=Date.now()>>>0;}const runId=window.crypto?.randomUUID?.()||`run-${Date.now()}-${seedBytes[0]}`;state=Game.createState({...config,seed:seedBytes[0],runId});state.player.personality=config.personality||'';state.player.goal=config.goal||'';const ok=persist();render(ok?'已创建并保存':'本次临时进度 · 尚未保存');}
function setWizard(step){setupStep=Math.max(1,Math.min(3,step));document.querySelectorAll('[data-wizard]').forEach(x=>x.hidden=Number(x.dataset.wizard)!==setupStep);document.querySelectorAll('.wizard-meter i').forEach((x,i)=>x.classList.toggle('current',i<setupStep));$('setup-eyebrow').textContent=`建立幸存者档案 · 0${setupStep} / 03`;$('setup-title').textContent=['','你从哪里开始？','你靠什么活下去？','确认幸存者档案'][setupStep];$('wizard-back').textContent=setupStep===1?'返回标题':'上一步';$('wizard-next').hidden=setupStep===3;$('wizard-submit').hidden=setupStep!==3;if(setupStep===3){const f=$('character-form');const val=n=>ui.esc(f.elements[n].value||'未填写');const origin={citizen:'普通市民',medic:'医护人员',mechanic:'维修工'};const trait={steady:'沉着',hunter:'天生猎手',healer:'快速愈合',iron:'钢铁意志'};const flaw={none:'无明显缺陷',old_injury:'旧伤',susceptible:'病毒易感',social:'社交障碍'};$('character-form').querySelector('.review-card').innerHTML=`<h3>角色档案</h3><p><strong>${val('name')}</strong> · ${val('age')} 岁 · ${origin[f.elements.origin.value]} · ${val('gender')}</p><p>天赋：${trait[f.elements.trait.value]}　缺陷：${flaw[f.elements.flaw.value]}</p><p>难度：${f.elements.difficulty.value==='easy'?'休闲':'标准'}　随机事件：${f.elements.randomEvents.value==='true'?'开启':'关闭'}</p><p>性格：${val('personality')}</p><p>人生目标：${val('goal')}</p><p>开局：普通武器、2 份口粮、2 瓶水。出身会调整技能与额外物资。</p><p>这组身份与能力开始后不能修改。你可以稍后用手动存档保留节点。</p>`;}}
function currentExport(){const copy=Game.clone(envelope);if(state)copy.slots.auto={state:Game.clone(state),savedAt:new Date().toISOString(),summary:{name:state.player.name,location:state.locationId,slotIndex:state.clock.slotIndex,phase:state.phase}};st.download(copy);}
function showSaves(){const slots=Object.entries(envelope.slots).map(([id,x])=>`<div class="item-row"><span><b>${id==='auto'?'自动槽':`手动槽 ${id.slice(-1)}`}</b> ${x?`${ui.esc(x.summary?.name||'幸存者')} · ${ui.esc(x.summary?.location)} · ${x.summary?.phase==='ended'?'已结局':`D${Math.floor((x.summary?.slotIndex||0)/5)+1}`}`:'空'}</span>${x?`<button data-loadslot="${id}">载入</button>`:''}</div>`).join('');ui.modal('存档管理',`<p>自动槽 1 个，手动槽 3 个。手动存档会记录当前事件节点或战斗回合。</p>${slots}<p>结局图鉴：${envelope.profile.endings.map(id=>Game.content.endings.find(x=>x.id===id)?.name||id).join('、')||'尚无解锁结局'}</p><p class="fine">更换浏览器、清除浏览器数据或改变网页来源不会自动继承存档。</p>`,[{label:'导出当前进度 JSON',run:currentExport},{label:'导入 JSON',run:chooseImport},{label:'手动保存当前进度',run:manualSave,primary:true}]);}
function manualSave(){if(!state||state.phase==='ended'){announce('没有可保存的活动游戏。');return;}const chosen=prompt('输入手动存档槽编号（1—3）：','1');if(chosen===null)return;if(!['1','2','3'].includes(chosen)){announce('槽位编号须为 1、2 或 3。');return;}try{envelope=st.save(envelope,state,`manual${chosen}`);announce(`已保存到手动槽 ${chosen}。`);render();}catch(e){announce(e.message);}}
function chooseImport(){const input=document.createElement('input');input.type='file';input.accept='application/json,.json';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;if(file.size>st.LIMIT){announce('文件超过 2 MB。');return;}try{const parsed=st.importText(await file.text());ui.modal('确认导入存档',`<p>存档版本 ${parsed.envelopeVersion}，包含自动槽${parsed.slots.auto?'（'+ui.esc(parsed.slots.auto.summary?.name||'幸存者')+'）':'（空）'}和结局图鉴。</p><p>确认后将覆盖当前浏览器的全部存档槽。</p>`,[{label:'取消'},{label:'确认覆盖',primary:true,run:()=>{try{envelope=st.write({...parsed,storeRevision:envelope.storeRevision+1});state=envelope.slots.auto?.state||null;render('存档已导入');announce('存档导入成功。');}catch(e){announce(e.message);}}}]);}catch(e){announce(`导入失败：${e.message}`);}});input.click();}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.id==='start-button'){setWizard(1);ui.view('setup');$('character-form').querySelector('input[name="name"]').focus();return;}if(t.id==='randomize-button'){const f=$('character-form'),pick=(name,values)=>f.elements[name].value=values[Math.floor(Math.random()*values.length)];pick('name',['林岸','周遥','陈北','许安','顾临']);pick('age',['18','24','31','42','57']);pick('origin',['citizen','medic','mechanic']);pick('trait',['steady','hunter','healer','iron']);pick('flaw',['none','old_injury','susceptible','social']);announce('已生成身份和能力组合；随机结果不提供隐藏属性。');return;}if(t.id==='wizard-next'){if(setupStep===1){const f=$('character-form');if(!f.elements.name.value.trim()||f.elements.name.value.trim().length>20||Number(f.elements.age.value)<18||Number(f.elements.age.value)>65||!Number.isInteger(Number(f.elements.age.value))){announce('先填写有效姓名（1—20 字）和 18—65 岁整数年龄。');return;}}setWizard(setupStep+1);return;}if(t.id==='wizard-back'){if(setupStep===1)ui.view('home');else setWizard(setupStep-1);return;}if(t.id==='continue-button'){const slot=envelope.slots.auto;if(!slot){announce('自动槽为空，没有可继续的进度。');return;}if(envelope.profile.terminalRuns.includes(slot.state.runId)){announce('永久死亡已锁定本局。');return;}state=slot.state;render();return;}if(t.id==='manual-button'){showSaves();return;}if(t.id==='help-button'){ui.modal('生存规则',`<ul><li>每天 5 个行动时段，共 D1/D2 十个时段；D3 清晨封锁。</li><li>移动和地点选择组成一个行动，只推进 1 个时段；查看地图、切换面板不耗时。</li><li>撤离有两条路：商业街的路线便笺 → 警戒站通行证，或调查地下通道。队伍需满足相邻移动条件。</li><li>HP 到 0 为死亡，INF 到 100 为转化；日终会消耗口粮和水，感染者也会受影响。</li><li>完成救援需先在诊所招募医生或在警戒站招募警员；也可独自撤离。</li><li>制造和休息只在安全屋，均消耗一个时段。背包里的治疗物品在探索时使用同样消耗一个时段。</li><li>自动存档每次完整行动保存；存档管理可以写手动槽、导入和导出 JSON。</li></ul><p>手机使用“剧情 / 地图 / 背包 / 任务 / 同伴”页签。键盘可用 Tab、Enter 和方向键操作原生控件。</p>`,[{label:'开始',primary:true}]);return;}if(t.id==='home-button'||t.id==='ending-home'){ui.view('home');$('save-status').textContent='离线单人游戏 · 无账户';return;}if(t.id==='restart-button'){setWizard(1);ui.view('setup');return;}if(t.dataset.screen){ui.view(t.dataset.screen);return;}if(t.dataset.choice){const c=t.dataset.choice;if(state.settings.endingHints&&Game.content.events[state.activeEvent.eventId].choices.find(x=>x.id===c)?.effects?.some(x=>x.type==='ending')&&!confirm('此选择将结束本局并记录结局。确认继续？'))return;command('CHOOSE',{choiceId:c});return;}if(t.dataset.move){command('MOVE',{to:t.dataset.move});return;}if(t.hasAttribute('data-rest')){command('REST');return;}if(t.dataset.use){command('USE_ITEM',{id:t.dataset.use});return;}if(t.dataset.craft){command('CRAFT',{id:t.dataset.craft});return;}if(t.dataset.combat){command('COMBAT_ACTION',{action:t.dataset.combat});return;}if(t.hasAttribute('data-endday')){ui.modal('结束当天？',`<p>将跳过 D${Math.floor(state.clock.slotIndex/5)+1} 剩余时段，依次执行截止任务、口粮与饮水消耗、感染结算和体力恢复。</p><p>这项操作无法撤回。你可以先完成撤离或支线目标。</p>`,[{label:'继续行动'},{label:'结束当天',primary:true,run:()=>command('END_DAY')}]);return;}if(t.hasAttribute('data-explore')){command('EXPLORE');return;}if(t.dataset.trade){command('TRADE',{id:t.dataset.trade});return;}if(t.dataset.train){command('TRAIN',{skill:t.dataset.train});return;}if(t.dataset.companion){command('SET_COMPANION',{id:t.dataset.companion});return;}if(t.dataset.tab){ui.activateTab(t.dataset.tab);return;}if(t.dataset.loadslot){const entry=envelope.slots[t.dataset.loadslot];if(!entry)return;if(envelope.profile.terminalRuns.includes(entry.state.runId)){announce('永久死亡已锁定本局，不能载入旧存档。');return;}if(state&&state.phase!=='ended'&&!confirm('载入会替换当前运行进度，确定？'))return;state=entry.state;ui.modal('存档已载入',`<p>${ui.esc(state.player.name)} · ${ui.esc(state.locationId)} · ${state.phase==='event'?'待选择事件':state.phase==='combat'?'战斗回合':'探索'}</p>`,[{label:'继续游戏',run:()=>render(),primary:true}]);return;}if(t.classList.contains('modal-close')){document.getElementById('modal').close();return;}});
$('character-form').addEventListener('submit',e=>{e.preventDefault();if(setupStep!==3)return;const f=e.currentTarget,d=new FormData(f),name=String(d.get('name')||'').trim(),age=Number(d.get('age'));if(name.length<1||name.length>20){announce('姓名须为 1—20 个字符。');setWizard(1);return;}if(!Number.isInteger(age)||age<18||age>65){announce('年龄须为 18—65 的整数。');setWizard(1);return;}newGame({name,age,gender:String(d.get('gender')||'').trim(),personality:String(d.get('personality')||'').slice(0,30),goal:String(d.get('goal')||'').trim().slice(0,60),origin:d.get('origin'),trait:d.get('trait'),flaw:d.get('flaw'),difficulty:d.get('difficulty'),randomEvents:d.get('randomEvents')==='true',showInf:f.elements.showInf.checked,endingHints:f.elements.endingHints.checked,permadeath:f.elements.permadeath.checked});});
$('ending-home').addEventListener('click',()=>ui.view('home'));$('restart-button').addEventListener('click',()=>ui.view('setup'));document.querySelector('.modal-close').addEventListener('click',()=>{const opener=document.activeElement;setTimeout(()=>opener?.focus?.(),0);});
window.addEventListener('storage',e=>{if(e.key===st.KEY&&e.newValue){const fresh=st.load();if(fresh.ok&&fresh.envelope.storeRevision!==envelope.storeRevision){conflict=true;render();announce('另一个标签页更新了存档。请返回标题后重新载入，当前页不能覆盖新版本。');}}});window.addEventListener('focus',()=>{const fresh=st.load();if(fresh.ok&&envelope&&fresh.envelope.storeRevision!==envelope.storeRevision){conflict=true;render();}});
window.addEventListener('DOMContentLoaded',()=>{initialize();});
})();
